  'rep.purchasesNote': 'Received and returned at receipt cost, ex VAT, on the day of the document. Invoiced is the total of the supplier invoices dated in the period.',
  'rep.problem': 'What is wrong',
  'rep.problem.NO_ANSWER': 'No answer from the provider',
  'rep.problem.WAITING': 'Still waiting',
  'rep.problem.NOT_IN_A_SALE': 'Approved, but in no sale',
  'rep.takenAt': 'Taken at',
  'rep.shift': 'Shift',
  'rep.amount': 'Amount',
  'rep.noExceptions': 'No card or QR payment needs checking.',
  'rep.paymentsNote': 'Open the shift to see its sales. At the till, “Check payment” asks the provider again; an approved payment in no sale is used by finishing that sale, or cancelled.',
  'guide.reports.t3': 'Under Analysis: sales by category and by branch (all branches at once), every discount and price change with who approved it, purchases by supplier, and card or QR payments that still need checking.',
  // Session 20: reservations and the supplier catalog (session 20).
  'inv.tab.reservations': 'Reservations',
  'inv.reserved': 'Reserved',
  'inv.available': 'Available',
  'inv.reserve': 'Reserve stock',
  'inv.reserveUntil': 'Hold until',
  'inv.reserveFor': 'For whom or why',
  'inv.reserveForHint': 'Maria, pick-up Saturday',
  'inv.reservationsLede': 'Stock set aside for a customer or a reason, so it is not sold to someone else. What is available to sell is what is on hand less what is reserved. Release it when it is collected, sold or no longer wanted.',
  'inv.showActive': 'Show only what is still reserved',
  'inv.showReleased': 'Also show released reservations',
  'inv.released': 'Released {date}',
  'inv.releasedShort': 'Released',
  'inv.expired': 'Expired',
  'inv.until': 'Until {date}',
  'inv.untilReleased': 'Until released',
  'inv.release': 'Release',
  'inv.releaseHint': 'Collected, sold or no longer wanted. The stock becomes available again.',
  'inv.noReservations': 'Nothing is reserved at this branch.',
  'inv.noReservationsAll': 'No reservations at this branch yet.',
  'pur.catalog': 'Supplier catalog',
  'pur.catalogEmpty': 'No items in this supplier’s catalog yet.',
  'pur.addCatalogItem': 'Add an item',
  'pur.editCatalogItem': 'Edit',
  'pur.removeCatalogItem': 'Remove',
  'pur.supplierSku': 'Supplier SKU',
  'pur.supplierItemName': 'Supplier’s name for it',
  'pur.catalogCostLabel': 'Cost from this supplier',
  'pur.catalogCost': 'Catalog cost',
  'pur.preferred': 'Preferred supplier',
  'guide.inventory.t4': 'A customer’s order or a layaway: under Reservations, press “Reserve stock”. Reserved units are not sold to anyone else; a branch that refuses sales below zero refuses those too. Press “Release” when they are collected or no longer wanted.',
  'guide.inventory.t5': 'Expiry, Lot holds and Batch trace (and the expired-stock rule in Settings) appear once an item keeps expiry dates; Packs once a pack is linked to its pieces. The part “Packs, expiry dates and recalls” explains them.',
  'guide.tingi.title': 'Packs, expiry dates and recalls',
  'guide.tingi.lede': 'For any shop that sells a pack by the piece (tingi) or keeps dated stock, and for a recall of a batch.',
  'guide.tingi.s1': 'Make the pack and the piece two products that count their stock, each with its own price and barcode: for example “Cigarettes (pack of 20)” and “Cigarette stick”, or a 25 kg rice sack and rice by the kilo.',
  'guide.tingi.s2': 'On the pack’s product page, under Packs and pieces (tingi), press “Link a pack and its pieces”, pick the piece and enter how many are in one pack.',
  'guide.tingi.s3': 'Sell the piece at the till as usual. When the pieces run out, the sale opens a pack by itself; Inventory → Packs lists every pack opened. To open packs for the shelf yourself, press “Open a pack” there.',
  'guide.tingi.s4': 'For dated goods, tick “Keeps expiry dates” on the product and enter the date (and the lot code, if you keep it) on each delivery line when you receive. Inventory → Expiry lists what is expired or close; “Write off” removes an expired lot as waste.',
  'guide.tingi.t1': 'Opening a pack moves no money in the books: the pieces take the pack’s cost.',
  'guide.tingi.t2': 'What expires first is sold first. Stock that came in without a date counts as the oldest and goes first.',
  'guide.tingi.t3': 'Inventory → Settings sets how many days ahead the stock keepers get an email about expiring lots. Low-stock emails come from the reorder points on Stock & value.',
  'guide.tingi.t4': 'For a recall, Inventory → Batch trace shows where a lot went (sales and customers) and what is left. Lot holds stops a lot from being sold until you release it; a held lot can still be written off.',
  'guide.tingi.t5': 'Inventory → Settings: choose whether a branch may sell expired stock. Allow is the starting choice; “Never sell expired” has the counter refuse expired lots. Held lots are never sold, whichever you choose.',
  'guide.purchasing.t3': 'On a supplier’s page, the supplier catalog keeps their SKU and cost for each item. A purchase order line left without a cost takes it from there, and the order shows their SKU.',
  'guide.purchasing.t4': 'On an invoice, “Record a credit or debit note” records what the supplier credits (goods returned after the invoice, an allowance) or charges on top. To pay several invoices of one supplier at once, use “Pay several invoices” on the invoices page.',
  'guide.purchasing.t5': 'A payment recorded by mistake is undone on its page with “Void payment” and a reason; its invoices are open again. Journal entries of invoices, payments and notes are never reversed by hand.',
  'guide.purchasing.t6': 'A delivery that came without an order is received with “Receive without an order” under “Goods receipts”: pick the supplier and the branch, and type each item’s quantity and cost.',
  'guide.purchasing.t7': 'Items that keep expiry dates ask for the date on the pack when received (and an optional lot code); the goods receipt shows them. A return to the supplier leaves from that delivery’s lot, or from the lot you pick under “Lot it leaves from”.',
  'guide.purchasing.t8': 'A supplier paid in cash at the shop: choose “Cash from a till drawer” as how it was paid and pick the drawer of an open shift at that branch. The drawer’s expected cash goes down by it and the shift lists it; voiding the payment puts the cash back into an open drawer.',
