  'guide.customers.lede': 'Itala ang mga customer na kailangan mong makilala: sino ang bumili ng ano, ang kanilang store credit, at kung gusto nila ng alok.',
  'guide.customers.s1': 'Buksan ang Mga customer mula sa Buod. Maghanap ayon sa pangalan, telepono, email o numero.',
  'guide.customers.s2': 'Pindutin ang “Magdagdag ng customer”. Sapat na ang pangalan; magdagdag lang ng telepono o email kung gagamitin mo ito. Lagyan lang ng tsek ang alok kung pumayag ang customer sa mga alok at balita, at sabihin kung paano sila pumayag.',
  'guide.customers.s3': 'Sa counter, inilalagay ng kahero ang customer sa benta. Lalabas na ang mga binili nila sa pahina ng customer.',
  'guide.customers.s4': 'Puwedeng i-refund ang isang balik bilang store credit sa halip na cash. Ginagamit ito ng customer sa counter, sa alinmang branch ng parehong kumpanya.',
  'guide.customers.s5': 'Kapag tinanong ng customer kung ano ang hawak mo tungkol sa kanila, pindutin ang “I-download ang kanilang datos”. Kapag hiniling nilang kalimutan sila, pindutin ang “Tanggalin ang personal na detalye” (pagkatapos magamit ang kanilang store credit).',
  'guide.customers.t1': 'Ang customer na nagsabing “ayaw na ng alok” ay agad itinatala, ng sinumang makakapagbukas ng customer, gamit ang “Bawiin ang pahintulot”.',
  'guide.customers.t2': 'Utang sa customer ang store credit: lumalabas ito sa libro bilang Customer store credit hanggang magamit.',
  // Session 20: reports added in session 20.
