  'rep.paymentsNote': 'Buksan ang shift para makita ang mga benta nito. Sa till, tinatanong muli ng “Suriin ang bayad” ang provider; ang aprubadong bayad na wala sa benta ay ginagamit sa pagtapos ng bentang iyon, o kinakansela.',
  'guide.reports.t3': 'Sa Pagsusuri: benta bawat kategorya at bawat branch (lahat ng branch nang sabay), bawat diskwento at pagbabago ng presyo at kung sino ang nag-apruba, mga binili bawat supplier, at mga card o QR na bayad na kailangan pang suriin.',
  // Session 20: reservations and the supplier catalog.
  'inv.tab.reservations': 'Mga reserba',
  'inv.reserved': 'Nakareserba',
  'inv.available': 'Maibebenta',
  'inv.reserve': 'Magreserba ng stock',
  'inv.reserveUntil': 'Hanggang',
  'inv.reserveFor': 'Para kanino o bakit',
  'inv.reserveForHint': 'Maria, kukunin sa Sabado',
  'inv.reservationsLede': 'Stock na itinabi para sa isang customer o dahilan, para hindi ito maibenta sa iba. Ang maibebenta ay ang nasa kamay bawas ang nakareserba. I-release ito kapag nakuha na, naibenta o hindi na kailangan.',
  'inv.showActive': 'Ipakita lang ang nakareserba pa',
