  'inv.noReservationsAll': 'Wala pang reserba sa branch na ito.',
  'pur.catalog': 'Katalogo ng supplier',
  'pur.catalogEmpty': 'Wala pang item sa katalogo ng supplier na ito.',
  'pur.addCatalogItem': 'Magdagdag ng item',
  'pur.editCatalogItem': 'I-edit',
  'pur.removeCatalogItem': 'Alisin',
  'pur.supplierSku': 'SKU ng supplier',
  'pur.supplierItemName': 'Pangalan nito sa supplier',
  'pur.catalogCostLabel': 'Halaga mula sa supplier na ito',
  'pur.catalogCost': 'Halaga sa katalogo',
  'pur.preferred': 'Pangunahing supplier',
  'guide.inventory.t4': 'Order ng customer o layaway: sa Mga reserba, pindutin ang “Magreserba ng stock”. Hindi naibebenta sa iba ang nakareserba; ang branch na tumatanggi sa bentang lalampas sa zero ay tumatanggi rin dito. Pindutin ang “I-release” kapag nakuha na o hindi na kailangan.',
  'guide.inventory.t5': 'Lumalabas ang Expiry, Hold sa lot at Subaybayan ang batch (at ang tuntunin sa expired na stock sa Mga setting) kapag may produktong may petsa ng expiry; ang Pakete kapag may paketeng naka-link sa mga piraso nito. Ipinapaliwanag sila sa bahaging “Pakete, petsa ng expiry at recall”.',
  'guide.tingi.title': 'Pakete, petsa ng expiry at recall',
  'guide.tingi.lede': 'Para sa anumang tindahang nagtitingi ng pakete o may stock na may petsa, at para sa recall ng isang batch.',
  'guide.tingi.s1': 'Gawing dalawang produktong binibilang ang stock ang pakete at ang piraso, bawat isa may sariling presyo at barcode: halimbawa “Sigarilyo (pakete ng 20)” at “Sigarilyo (isang stick)”, o isang 25 kg na sako ng bigas at bigas na kilo-kilo.',
  'guide.tingi.s2': 'Sa pahina ng produkto ng pakete, sa Pakete at tingi, pindutin ang “Iugnay ang pakete at ang mga piraso nito”, piliin ang piraso at ilagay kung ilan ang laman ng isang pakete.',
  'guide.tingi.s3': 'Ibenta ang piraso sa kaha gaya ng dati. Kapag naubos ang piraso, kusang nagbubukas ng pakete ang benta; nakalista sa Imbentaryo → Pakete ang bawat binuksang pakete. Para magbukas ng pakete para sa estante, pindutin doon ang “Magbukas ng pakete”.',
  'guide.tingi.s4': 'Para sa may petsa, lagyan ng tsek ang “May petsa ng expiry” sa produkto at ilagay ang petsa (at ang lot code, kung itinatala mo) sa bawat linya ng delivery kapag tumatanggap. Nakalista sa Imbentaryo → Expiry ang expired o malapit na; inaalis ng “I-write off” ang expired na lot bilang sayang.',
  'guide.tingi.t1': 'Walang perang gumagalaw sa libro sa pagbubukas ng pakete: kinukuha ng mga piraso ang halaga ng pakete.',
  'guide.tingi.t2': 'Ang unang mag-e-expire ang unang mabebenta. Ang stock na pumasok nang walang petsa ay itinuturing na pinakaluma at nauuna.',
  'guide.tingi.t3': 'Sa Imbentaryo → Mga setting itinatakda kung ilang araw bago makatanggap ng email ang mga may hawak ng stock tungkol sa mag-e-expire. Ang email sa paubos na stock ay galing sa mga reorder point sa Stock at halaga.',
  'guide.tingi.t4': 'Sa recall, ipinapakita ng Imbentaryo → Subaybayan ang batch kung saan napunta ang lot (mga benta at customer) at ang natitira. Pinipigilan ng Hold sa lot ang pagbenta nito hanggang i-release mo; puwede pa ring i-write off ang naka-hold na lot.',
  'guide.tingi.t5': 'Imbentaryo → Mga setting: piliin kung puwedeng magbenta ng expired ang branch. Payagan ang simula; sa “Huwag magbenta ng expired”, tatanggihan ng kaha ang expired na lot. Hindi kailanman ibinebenta ang naka-hold na lot, alinman ang piliin mo.',
  'guide.purchasing.t3': 'Sa pahina ng supplier, nasa katalogo ng supplier ang kanilang SKU at halaga para sa bawat item. Ang linya ng purchase order na walang halaga ay kukuha nito roon, at ipapakita ng order ang kanilang SKU.',
  'guide.purchasing.t4': 'Sa invoice, itinatala ng “Magtala ng credit o debit note” ang ibinabawas ng supplier (paninda na ibinalik pagkatapos ng invoice, diskwento) o idinadagdag nito. Para bayaran nang sabay ang ilang invoice ng isang supplier, gamitin ang “Bayaran ang ilang invoice” sa pahina ng mga invoice.',
  'guide.purchasing.t5': 'Ang bayad na naitala nang mali ay binabawi sa pahina nito gamit ang “I-void ang bayad” at dahilan; bukas ulit ang mga invoice nito. Hindi kailanman binabaliktad nang mano-mano ang journal entry ng invoice, bayad at note.',
  'guide.purchasing.t6': 'Ang delivery na dumating nang walang order ay tinatanggap gamit ang “Tumanggap nang walang order” sa ilalim ng “Mga goods receipt”: piliin ang supplier at branch, at itipa ang dami at halaga ng bawat item.',
  'guide.purchasing.t7': 'Ang mga item na may expiry ay humihingi ng petsa sa pakete pagtanggap (at opsyonal na lot code); makikita ang mga ito sa goods receipt. Ang ibinabalik sa supplier ay kinukuha sa lot ng delivery na iyon, o sa lot na pipiliin mo sa “Lot na pagkukunan”.',
  'guide.purchasing.t8': 'Supplier na binayaran ng cash sa tindahan: piliin ang “Cash mula sa drawer ng till” bilang paraan ng bayad at ang drawer ng bukas na shift sa branch na iyon. Bababa ang inaasahang cash ng drawer at makikita ito sa shift; kapag na-void ang bayad, ibinabalik ang cash sa isang bukas na drawer.',
